def search(query=None, nation=None, sector=None, technique=None):
    results = APT_DATABASE
    if query:
        q = query.lower()
        results = [a for a in results if q in a["name"].lower() or any(q in alias.lower() for alias in a["aliases"]) or q in a.get("description", "").lower()]
    if nation:
        n = nation.lower()
        results = [a for a in results if n in a["nation"].lower()]
    if sector:
        s = sector.lower()
        results = [a for a in results if any(s in sec for sec in a["sectors"])]
    if technique:
        results = [a for a in results if technique in a.get("ttps", [])]
    return results

def who_targets(sector, region=None):
    """Given an industry sector (and optional region), return likely threat actors."""
    s = sector.lower()
    results = [a for a in APT_DATABASE if any(s in sec for sec in a["sectors"]) or "any" in a["sectors"]]
    if region:
        r = region.lower()
        results = [a for a in results if any(r in reg.lower() for reg in a.get("regions", []))]
    return sorted(results, key=lambda a: a["active_since"])

def get_stats():
    total = len(APT_DATABASE)
    by_nation = {}
    for a in APT_DATABASE:
        n = a["nation"].split("-")[0].strip().split(" ")[0]
        by_nation[n] = by_nation.get(n, 0) + 1
    return {"total": total, "by_nation": by_nation}

if __name__ == "__main__":
    stats = get_stats()
    print(f"AEGIS APT Database: {stats['total']} threat actor profiles")
    for nation, count in sorted(stats["by_nation"].items(), key=lambda x: -x[1]):
        print(f"  {nation}: {count}")
